private int inBuff = 0;
private int inDemand = 0;
private int outBuff = 0;
private int outBuffRetained = 0;
private int outDemand = 0;
private boolean valid = true;
private int pulled = 0;
private int pushed = 0;
private int nodeCount = 0;
private static final int MAX_BUFF = 80000;

public EnergyNetwork(Level world) {
    EnergyNetworkManager.instances.get(world).add(this);
}

public int getMaxBuff() {
    return Math.min(this.nodeCount * (this.outDemand + this.inDemand * 2 + 10), 80000);
}

public void tick(int index) {
    this.id = index;
    int t = this.outBuff;
    this.outBuffRetained = this.outBuff = this.inBuff;
    this.inBuff = t;
    this.outDemand = this.inDemand;
    this.inDemand = 0;
    this.pulled = 0;
    this.pushed = 0;
}

public int getBuff() {
    return this.outBuffRetained;
}

public int push(int energy, boolean simulate) {
    energy = Math.min(this.getMaxBuff() - this.inBuff, energy);
    energy = Math.max(energy, 0);
    if (!simulate) {
        this.inBuff += energy;
        this.pushed += energy;
    }
    return energy;
}

public int push(int energy) {
    return this.push(energy, false);
}

